// ---------------------------------------------------------------------
//  Uebersetzung Abi-Signatur -> Java-Methodenkopf (alle Methoden der
//  Akademie sind public static):
//
//      Abi-Notation                 Java
//      ------------------------------------------------------------
//      Ganzzahl                     int
//      Kommazahl                    double
//      Wahrheitswert                boolean
//      Zeichen                      char
//      Zeichenkette                 String
//      Reihung von Ganzzahl         int[]
//      nichts                       void
//
//      name(p: Typ, q: Typ): Rueckgabetyp
//      ->  public static Rueckgabetyp name(Typ p, Typ q) { ... }
