    public void experte_ggT() {
        assertEquals(6, Werkstatt.ggT(12, 18), "ggT(12, 18) = 6");
        assertEquals(6, Werkstatt.ggT(18, 12), "ggT(18, 12) = 6 - die Reihenfolge der Zahlen darf keine Rolle spielen");
        assertEquals(25, Werkstatt.ggT(100, 75), "ggT(100, 75) = 25");
        assertEquals(12, Werkstatt.ggT(48, 180), "ggT(48, 180) = 12");
    }

    @Test
    public void experte_ggT_sonderfaelle() {
        assertEquals(1, Werkstatt.ggT(7, 13), "7 und 13 sind teilerfremd: ggT = 1");
        assertEquals(5, Werkstatt.ggT(5, 5), "ggT(5, 5) = 5");
        assertEquals(3, Werkstatt.ggT(9, 3), "3 teilt 9: ggT(9, 3) = 3");
        assertEquals(1, Werkstatt.ggT(1, 9), "ggT(1, 9) = 1");
    }

    @Test
    public void experte_istPrimzahl_klein() {
        assertTrue(Werkstatt.istPrimzahl(2), "2 ist die kleinste Primzahl");
        assertTrue(Werkstatt.istPrimzahl(3), "3 ist eine Primzahl");
        assertFalse(Werkstatt.istPrimzahl(4), "4 = 2 * 2 ist keine Primzahl");
        assertTrue(Werkstatt.istPrimzahl(97), "97 ist eine Primzahl");
    }

    @Test
    public void experte_istPrimzahl_quadratzahlen() {
        assertFalse(Werkstatt.istPrimzahl(9), "9 = 3 * 3 ist keine Primzahl - laeuft dein Teiler weit genug?");
        assertFalse(Werkstatt.istPrimzahl(25), "25 = 5 * 5 ist keine Primzahl - Grenze t * t <= n (mit Gleichheit!)");
        assertFalse(Werkstatt.istPrimzahl(91), "91 = 7 * 13 ist keine Primzahl");
        assertTrue(Werkstatt.istPrimzahl(29), "29 ist eine Primzahl");
    }

    @Test
    public void experte_istPrimzahl_kleinerZwei() {
        assertTrue(Werkstatt.istPrimzahl(5), "5 ist eine Primzahl");
        assertFalse(Werkstatt.istPrimzahl(1), "1 ist KEINE Primzahl (fuer n < 2 gilt: false)");
        assertFalse(Werkstatt.istPrimzahl(0), "0 ist keine Primzahl");
        assertFalse(Werkstatt.istPrimzahl(-7), "Negative Zahlen sind keine Primzahlen");
    }
}


