    }

    @Test
    public void basis_letzterWert_randfaelle() {
        int[] eins = {9};
        assertEquals(9, Vorrat.letzterWert(eins), "Bei einem Element ist das erste auch das letzte: 9");
        int[] leer = new int[0];
        assertEquals(-1, Vorrat.letzterWert(leer), "Leere Reihung: letzterWert muss -1 liefern - frage r.length == 0 VOR dem Zugriff ab");
