    @Test
    public void basis_enthaelt() {
        int[] r = {4, 7, 9};
        assertTrue(Vorrat.enthaelt(r, 4), "4 steht ganz vorne in {4, 7, 9}");
        assertTrue(Vorrat.enthaelt(r, 9), "9 steht ganz hinten in {4, 7, 9} - wird das letzte Element geprueft?");
        assertTrue(Vorrat.enthaelt(r, 7), "7 steht in {4, 7, 9}");
        assertFalse(Vorrat.enthaelt(r, 5), "5 steht NICHT in {4, 7, 9}");
    }

    @Test
    public void basis_enthaelt_leerUndNegativ() {
