        int[] ungerade = {1, 2, 3};
        assertEquals("{3, 2, 1}", Anzeige.text(Vorrat.umgedreht(ungerade)), "umgedreht({1, 2, 3}) falsch - neu[i] = r[r.length - 1 - i]");
    }

    @Test
    public void erweiterung_umgedreht_originalUnveraendert() {
