        assertEquals(2, Vorrat.zaehleZeichen("Abrakadabra", 'b'), "'Abrakadabra' enthaelt 2 b");
        assertEquals(0, Vorrat.zaehleZeichen("Abrakadabra", 'z'), "'Abrakadabra' enthaelt kein z");
    }

    @Test
