    @Test
    public void experte_ohneVokale() {
        assertEquals("Zbrsprch", Vorrat.ohneVokale("Zauberspruch"), "ohneVokale('Zauberspruch') falsch");
        assertEquals("s", Vorrat.ohneVokale("Oase"), "ohneVokale('Oase') falsch - auch grosse Vokale entfernen");
        assertEquals("Drchn", Vorrat.ohneVokale("Drachen"), "ohneVokale('Drachen') falsch");
    }

    @Test
    public void experte_ohneVokale_randfaelle() {
        assertEquals("xyz", Vorrat.ohneVokale("xyz"), "Ohne Vokale bleibt die Zeichenkette gleich");
        assertEquals("", Vorrat.ohneVokale("AEIOUaeiou"), "Nur Vokale: Es bleibt die leere Zeichenkette");
        assertEquals("", Vorrat.ohneVokale(""), "Aus der leeren Zeichenkette wird die leere Zeichenkette");
    }

    @Test
    public void experte_beginntMit() {
        assertTrue(Vorrat.beginntMit("Feuerball", "Feuer"), "'Feuerball' beginnt mit 'Feuer'");
        assertTrue(Vorrat.beginntMit("Feuerball", "F"), "'Feuerball' beginnt mit 'F'");
        assertTrue(Vorrat.beginntMit("Feuerball", "Feuerball"), "Jede Zeichenkette beginnt mit sich selbst");
        assertFalse(Vorrat.beginntMit("Eisball", "Feuer"), "'Eisball' beginnt nicht mit 'Feuer'");
        assertFalse(Vorrat.beginntMit("Feuerball", "Fenster"), "'Feuerball' beginnt nicht mit 'Fenster' - es muessen ALLE Zeichen von anfang verglichen werden, nicht nur das erste");
        assertFalse(Vorrat.beginntMit("Feuerball", "ball"), "'Feuerball' ENTHAELT 'ball', beginnt aber nicht damit");
        assertFalse(Vorrat.beginntMit("Feuerball", "feuer"), "Gross-/Kleinschreibung zaehlt: 'Feuerball' beginnt nicht mit 'feuer'");
    }

    @Test
    public void experte_beginntMit_randfaelle() {
        assertTrue(Vorrat.beginntMit("Feuer", ""), "Jede Zeichenkette beginnt mit der leeren Zeichenkette");
        assertFalse(Vorrat.beginntMit("Feu", "Feuer"), "anfang ist laenger als s: false - pruefe die Laengen VOR dem Zugriff");
        assertFalse(Vorrat.beginntMit("", "a"), "Die leere Zeichenkette beginnt mit keinem Zeichen");
        assertTrue(Vorrat.beginntMit("", ""), "'' beginnt mit ''");
    }
}


