    }

    @Test
    public void basis_istStaerker() {
        assertTrue(Zauber.istStaerker(5, 3), "5 ist staerker als 3");
        assertFalse(Zauber.istStaerker(3, 5), "3 ist nicht staerker als 5");
        assertFalse(Zauber.istStaerker(4, 4), "Gleich stark ist NICHT staerker (a > b, nicht a >= b)");
