    }

    @Test
    public void basis_max2() {
        assertEquals(8, Zauber.max2(3, 8), "max2(3, 8) = 8");
        assertEquals(8, Zauber.max2(8, 3), "max2(8, 3) = 8 - die Reihenfolge darf keine Rolle spielen");
        assertEquals(5, Zauber.max2(5, 5), "max2(5, 5) = 5");
        assertEquals(-2, Zauber.max2(-2, -7), "max2(-2, -7) = -2");
    }


    @Test
    public void erweiterung_manaKosten() {
        assertEquals(30, Zauber.manaKosten(3, false), "Stufe 3, nicht verstaerkt: 10 * 3 = 30 Mana");
        assertEquals(10, Zauber.manaKosten(1, false), "Stufe 1, nicht verstaerkt: 10 Mana");
        assertEquals(60, Zauber.manaKosten(3, true), "Stufe 3, verstaerkt: doppelt so teuer = 60 Mana");
        assertEquals(100, Zauber.manaKosten(5, true), "Stufe 5, verstaerkt: 2 * 50 = 100 Mana");
    }

    @Test
    public void erweiterung_manaKosten_stufeNull() {
        assertEquals(0, Zauber.manaKosten(0, false), "Stufe 0 kostet 0 Mana");
        assertEquals(0, Zauber.manaKosten(0, true), "Stufe 0 kostet auch verstaerkt 0 Mana");
    }

    @Test
    public void erweiterung_kannZaubern() {
        assertTrue(Zauber.kannZaubern(30, 3, false), "30 Mana reichen GENAU fuer Stufe 3 (30 Mana) - mana >= Kosten");
        assertFalse(Zauber.kannZaubern(29, 3, false), "29 Mana reichen nicht fuer Stufe 3 (30 Mana)");
        assertFalse(Zauber.kannZaubern(59, 3, true), "59 Mana reichen nicht fuer Stufe 3 verstaerkt (60 Mana)");
        assertTrue(Zauber.kannZaubern(60, 3, true), "60 Mana reichen genau fuer Stufe 3 verstaerkt");
        assertTrue(Zauber.kannZaubern(100, 1, true), "100 Mana reichen fuer Stufe 1 verstaerkt (20 Mana)");
    }

    @Test
    public void erweiterung_kannZaubern_passtZuManaKosten() {
        for (int stufe = 0; stufe <= 6; stufe++) {
            for (int mana = 0; mana <= 130; mana = mana + 5) {
                boolean normal = mana >= Zauber.manaKosten(stufe, false);
                if (Zauber.kannZaubern(mana, stufe, false) != normal) {
                    fail("kannZaubern(" + mana + ", " + stufe + ", false) passt nicht zu manaKosten(" + stufe + ", false) = " + Zauber.manaKosten(stufe, false) + " - rufe manaKosten auf, statt neu zu rechnen");
                }
                boolean verstaerkt = mana >= Zauber.manaKosten(stufe, true);
                if (Zauber.kannZaubern(mana, stufe, true) != verstaerkt) {
                    fail("kannZaubern(" + mana + ", " + stufe + ", true) passt nicht zu manaKosten(" + stufe + ", true) = " + Zauber.manaKosten(stufe, true) + " - rufe manaKosten auf, statt neu zu rechnen");
                }
            }
        }
    }

    @Test
    public void erweiterung_max3() {
