        assertFalse(TestHilfe.standard().hatDoppelteNamen(), "Standardliste: alle Namen verschieden - vergleichst du einen Eintrag mit sich selbst?");
    }

    @Test
    public void experte_hatDoppelteNamen_randfaelle() {
        String[] namen = {"Aria", "Brann", "Cyra", "Cyra"};
        int[] punkte = {1200, 800, 1500, 700};
        Rangliste r = TestHilfe.liste(10, namen, punkte);
        assertTrue(r.hatDoppelteNamen(), "Cyra steht an Index 2 und 3 (die letzten beiden): hatDoppelteNamen() muss true liefern");
