        String teil = "Ar";
        Rangliste r3 = new Rangliste(5);
        r3.hinzufuegen(new Eintrag("Aria", 100, 60));
        r3.hinzufuegen(new Eintrag(teil + "ia", 200, 70));
        assertTrue(r3.hatDoppelteNamen(), "Namen mit equals vergleichen: 'Aria' und ein zur Laufzeit gebautes 'Aria' sind gleich");
    }
}


