    private Rangliste absteigend6() {
        String[] namen = {"A", "B", "C", "D", "E", "F"};
        int[] punkte = {60, 50, 40, 30, 20, 10};
        return TestHilfe.liste(10, namen, punkte);
    }

    // n = 6, AUFSTEIGEND sortiert (fuer die Rangliste der schlechteste Fall)
    private Rangliste aufsteigend6() {
        String[] namen = {"A", "B", "C", "D", "E", "F"};
        int[] punkte = {10, 20, 30, 40, 50, 60};
        return TestHilfe.liste(10, namen, punkte);
