    public void basis_istSortiert() {
        String[] namen = {"Cyra", "Aria", "Dorn", "Brann"};
        int[] punkte = {1500, 1200, 950, 800};
        assertTrue(TestHilfe.liste(10, namen, punkte).istSortiert(), "1500, 1200, 950, 800 ist absteigend sortiert");
