        assertEquals(5, r.getAnzahl(), "Beim Sortieren darf kein Eintrag verloren gehen");
    }

    @Test
    public void basis_insertionSort() {
        Rangliste r = sortierListe();
        r.insertionSort();
        assertEquals("Cyra,Aria,Dorn,Brann,Elin", TestHilfe.namen(r), "insertionSort muss absteigend nach Punkten sortieren (Platz 1 = meiste Punkte)");
