        assertEquals("A,B,C,D,E,F", TestHilfe.namen(r), "Eine schon sortierte Liste bleibt unveraendert");
        assertEquals(5, r.getVergleiche(), "insertionSort bei sortierter Liste (n = 6): genau n - 1 = 5 Vergleiche - bricht deine innere Schleife ab?");
        assertEquals(0, r.getVertauschungen(), "insertionSort bei sortierter Liste: 0 Vertauschungen");
    }

    @Test
