        assertEquals(5, r.getVergleiche(), "bubbleSort bei sortierter Liste (n = 6): genau n - 1 = 5 Vergleiche - Abbruch, wenn ein Durchlauf ohne Vertauschung blieb!");
        assertEquals(0, r.getVertauschungen(), "bubbleSort bei sortierter Liste: 0 Vertauschungen");
    }

