        for (int i = 0; i < strategien.length; i++) {
            MeinSolver.strategie = strategien[i];
            int summe = 0;
            String zeile = strategien[i] + ":";
            for (int nr = 1; nr <= 3; nr++) {
                Rennen.training(nr);
                zeile = zeile + "  Karte " + nr + " = " + Rennen.getSchritte();
                summe = summe + Rennen.getSchritte();
            }
            println("REFERENZ " + zeile + "  | Summe = " + summe);
        }
        MeinSolver.strategie = "kompass";
    }
}


