    @Test
    public void experte_meinStapel_grundlagen() {
        try {
            MeinStapel m = new MeinStapel();
            assertTrue(m.isEmpty(), "Ein neuer MeinStapel ist leer");
            Kiste[] k = Testhilfe.ladung();
            m.push(k[1]);
            m.push(k[0]);
            m.push(k[2]);
            assertFalse(m.isEmpty(), "Nach push ist MeinStapel nicht leer");
            assertTrue(m.top() == k[2], "top: Gold wurde zuletzt gepusht und liegt oben");
            assertTrue(m.top() == k[2], "top entfernt nichts: wieder Gold");
            assertTrue(m.pop() == k[2], "pop: Gold");
            assertTrue(m.pop() == k[0], "pop: Holz");
            assertFalse(m.isEmpty(), "Erz liegt noch im Stapel");
            assertTrue(m.pop() == k[1], "pop: Erz");
            assertTrue(m.isEmpty(), "Jetzt ist MeinStapel wieder leer");
            m.push(k[5]);
            assertTrue(m.pop() == k[5], "push und pop auf einem wieder leeren Stapel: Wein");
        } catch (RuntimeException e) {
            Testhilfe.laufzeitfehler(e);
        }
    }

    @Test
    public void experte_meinStapel_leer() {
        MeinStapel m = new MeinStapel();
        boolean geworfen = false;
        try {
            m.top();
        } catch (IllegalStateException e) {
            geworfen = true;
        } catch (RuntimeException e) {
            fail("top() auf leerem MeinStapel: falscher Laufzeitfehler - erwartet wird eine IllegalStateException (Leerabfrage + throw new IllegalStateException(...))");
        }
        assertTrue(geworfen, "top() auf leerem MeinStapel muss eine IllegalStateException werfen - wie Stack");
        geworfen = false;
        try {
            m.push("Erz");
            m.pop();
            m.pop();
        } catch (IllegalStateException e) {
            geworfen = true;
        } catch (RuntimeException e) {
            fail("pop() auf leerem MeinStapel: falscher Laufzeitfehler - erwartet wird eine IllegalStateException (Leerabfrage + throw new IllegalStateException(...))");
        }
        assertTrue(geworfen, "pop() auf leerem MeinStapel muss eine IllegalStateException werfen - wie Stack");
        assertTrue(m.isEmpty(), "Nach dem Fehlversuch ist MeinStapel leer");
    }

    @Test
    public void experte_meinStapel_zufallsvergleich() {
        try {
            Stack original = new Stack();
            MeinStapel mein = new MeinStapel();
            int x = 2026;
            int maxHoehe = 0;
            int hoehe = 0;
            for (int schritt = 1; schritt <= 400; schritt++) {
                x = Testhilfe.naechsteZufallszahl(x);
                int befehl = x % 3;
                if (befehl == 0) {
                    original.push(x);
                    mein.push(x);
                    hoehe++;
                } else if (!original.isEmpty()) {
                    if (befehl == 1) {
                        int a = (Integer) original.pop();
                        int b = (Integer) mein.pop();
                        assertEquals(a, b, "Schritt " + schritt + ": pop liefert bei Stack und MeinStapel verschiedene Werte");
                        hoehe--;
                    } else {
                        int a = (Integer) original.top();
                        int b = (Integer) mein.top();
                        assertEquals(a, b, "Schritt " + schritt + ": top liefert bei Stack und MeinStapel verschiedene Werte");
                    }
                }
                if (hoehe > maxHoehe) {
                    maxHoehe = hoehe;
                }
                assertEquals(original.isEmpty(), mein.isEmpty(), "Schritt " + schritt + ": isEmpty() bei Stack und MeinStapel verschieden");
            }
            while (!original.isEmpty()) {
                int a = (Integer) original.pop();
                int b = (Integer) mein.pop();
                assertEquals(a, b, "Abbauen am Ende: pop liefert verschiedene Werte");
            }
            assertTrue(mein.isEmpty(), "Am Ende muessen beide Stapel leer sein");
            assertTrue(maxHoehe >= 3, "(Selbstkontrolle des Tests: Der Stapel war mindestens 3 hoch)");
        } catch (RuntimeException e) {
            Testhilfe.laufzeitfehler(e);
        }
    }
