class L51BaumTest {

    @Test
    public void basis_anzahlKnoten() {
        try {
            assertEquals(9, Baum.anzahlKnoten(Baumschule.beispielBST()), "anzahlKnoten(beispielBST): 9 Knoten");
            assertEquals(7, Baum.anzahlKnoten(Baumschule.zahlenbaum()), "anzahlKnoten(zahlenbaum): 7 Knoten");
            assertEquals(5, Baum.anzahlKnoten(Baumschule.entartet()), "anzahlKnoten(entartet): 5 Knoten");
            assertEquals(7, Baum.anzahlKnoten(Baumschule.termbaum()), "anzahlKnoten(termbaum): 7 Knoten (auch Rechenzeichen sind Knoten)");
            assertEquals(1, Baum.anzahlKnoten(Baumschule.blatt(42)), "anzahlKnoten eines Blatts: 1");
            assertEquals(0, Baum.anzahlKnoten(Baumschule.leer()), "anzahlKnoten des leeren Baums: 0 (Basisfall if (b.isEmpty()))");
        } catch (RuntimeException e) {
            Testhilfe.laufzeitfehler(e);
        }
    }

    @Test
    public void basis_preorder() {
        try {
            BinTree b = Baumschule.beispielBST();
            assertEquals("8 3 1 6 4 7 10 14 13 ", Baum.preorder(b), "preorder(beispielBST): Wurzel - links - rechts, nach JEDEM Element ein Leerzeichen");
            assertEquals("8(3(1,6(4,7)),10(-,14(13,-)))", Testhilfe.klammer(b), "preorder darf den Baum NICHT veraendern");
            assertEquals("5 9 2 7 4 9 1 ", Baum.preorder(Baumschule.zahlenbaum()), "preorder(zahlenbaum)");
            assertEquals("* + 3 4 - 5 2 ", Baum.preorder(Baumschule.termbaum()), "preorder(termbaum): Praefix-Schreibweise des Terms");
            assertEquals("42 ", Baum.preorder(Baumschule.blatt(42)), "preorder eines Blatts: '42 ' (mit Leerzeichen)");
            assertEquals("", Baum.preorder(Baumschule.leer()), "preorder des leeren Baums: die leere Zeichenkette");
        } catch (RuntimeException e) {
            Testhilfe.laufzeitfehler(e);
        }
    }

    @Test
    public void basis_inorder() {
        try {
            assertEquals("1 3 4 6 7 8 10 13 14 ", Baum.inorder(Baumschule.beispielBST()), "inorder(beispielBST): links - Wurzel - rechts (beim BST aufsteigend sortiert!)");
            assertEquals("2 9 7 5 4 1 9 ", Baum.inorder(Baumschule.zahlenbaum()), "inorder(zahlenbaum)");
            assertEquals("3 + 4 * 5 - 2 ", Baum.inorder(Baumschule.termbaum()), "inorder(termbaum): der Term ohne Klammern");
            assertEquals("1 2 3 4 5 ", Baum.inorder(Baumschule.entartet()), "inorder(entartet)");
            assertEquals("", Baum.inorder(Baumschule.leer()), "inorder des leeren Baums: die leere Zeichenkette");
        } catch (RuntimeException e) {
            Testhilfe.laufzeitfehler(e);
        }
    }

    @Test
    public void basis_postorder() {
        try {
            assertEquals("1 4 7 6 3 13 14 10 8 ", Baum.postorder(Baumschule.beispielBST()), "postorder(beispielBST): links - rechts - Wurzel");
            assertEquals("2 7 9 1 9 4 5 ", Baum.postorder(Baumschule.zahlenbaum()), "postorder(zahlenbaum)");
            assertEquals("3 4 + 5 2 - * ", Baum.postorder(Baumschule.termbaum()), "postorder(termbaum): Postfix-Schreibweise (wie im Postfix-Rechner aus Welt 4)");
            assertEquals("5 4 3 2 1 ", Baum.postorder(Baumschule.entartet()), "postorder(entartet)");
            assertEquals("", Baum.postorder(Baumschule.leer()), "postorder des leeren Baums: die leere Zeichenkette");
        } catch (RuntimeException e) {
            Testhilfe.laufzeitfehler(e);
        }
    }

    @Test
    public void erweiterung_hoehe() {
        try {
            assertEquals(4, Baum.hoehe(Baumschule.beispielBST()), "hoehe(beispielBST): 4 Ebenen");
            assertEquals(4, Baum.hoehe(Baumschule.zahlenbaum()), "hoehe(zahlenbaum): 4 (der laengste Weg geht nach rechts: 5, 4, 9, 1)");
            assertEquals(5, Baum.hoehe(Baumschule.entartet()), "hoehe(entartet): 5");
            assertEquals(3, Baum.hoehe(Baumschule.termbaum()), "hoehe(termbaum): 3");
            BinTree linksLang = Baumschule.knoten(1, Baumschule.knoten(2, Baumschule.blatt(3), Baumschule.leer()), Baumschule.leer());
            assertEquals(3, Baum.hoehe(linksLang), "hoehe von 1(2(3,-),-): 3 - der LINKE Teilbaum ist hier der hoehere");
            assertEquals(1, Baum.hoehe(Baumschule.blatt(42)), "hoehe eines Blatts: 1");
            assertEquals(0, Baum.hoehe(Baumschule.leer()), "hoehe des leeren Baums: 0");
        } catch (RuntimeException e) {
            Testhilfe.laufzeitfehler(e);
        }
    }

    @Test
    public void erweiterung_anzahlBlaetter() {
        try {
            assertEquals(4, Baum.anzahlBlaetter(Baumschule.beispielBST()), "anzahlBlaetter(beispielBST): 4 (1, 4, 7, 13)");
            assertEquals(3, Baum.anzahlBlaetter(Baumschule.zahlenbaum()), "anzahlBlaetter(zahlenbaum): 3 (2, 7, 1)");
            assertEquals(1, Baum.anzahlBlaetter(Baumschule.entartet()), "anzahlBlaetter(entartet): 1 (nur die 5)");
            assertEquals(4, Baum.anzahlBlaetter(Baumschule.termbaum()), "anzahlBlaetter(termbaum): 4 Zahlen");
            BinTree halb = Baumschule.knoten(1, Baumschule.leer(), Baumschule.knoten(2, Baumschule.blatt(3), Baumschule.blatt(4)));
            assertEquals(2, Baum.anzahlBlaetter(halb), "anzahlBlaetter von 1(-,2(3,4)): 2 - die 1 hat nur EIN leeres Kind und ist deshalb KEIN Blatt");
            assertEquals(1, Baum.anzahlBlaetter(Baumschule.blatt(42)), "anzahlBlaetter eines Blatts: 1");
            assertEquals(0, Baum.anzahlBlaetter(Baumschule.leer()), "anzahlBlaetter des leeren Baums: 0 (isLeaf erst NACH isEmpty pruefen!)");
        } catch (RuntimeException e) {
            Testhilfe.laufzeitfehler(e);
        }
    }

