    // Mila aus Abbildung 2: zuerst Spinne geklettert, zuletzt Sandmann.
    // Tourenbuch von OBEN: Sandmann, Wolkenkratzer, Dachrinne, Sandmann, Spinne
    public static Mitglied mila(Route[] r) {
