        t[3] = new Mitglied("Mo", 31);
        t[4] = new Mitglied("Nele", 38);
        t[5] = new Mitglied("Ole", 52);
        return t;
    }

    // Bestenliste aus Abbildung 12 (binaerer Suchbaum nach Punkten);
    // die Mitglieder sind ZaehlMitglieder (merken sich getPunkte-Aufrufe)
    public static BinTree bestenliste() {
        BinTree b = new BinTree();
        einfuegen(b, new ZaehlMitglied("Tim", 60));
        einfuegen(b, new ZaehlMitglied("Ida", 35));
        einfuegen(b, new ZaehlMitglied("Vera", 82));
        einfuegen(b, new ZaehlMitglied("Bo", 20));
        einfuegen(b, new ZaehlMitglied("Lou", 48));
        einfuegen(b, new ZaehlMitglied("Rae", 71));
        einfuegen(b, new ZaehlMitglied("Zoe", 95));
        einfuegen(b, new ZaehlMitglied("Gus", 41));
        einfuegen(b, new ZaehlMitglied("Sam", 55));
        return b;
    }

    // Einfuegen in den Suchbaum (Vergleich ueber das Attribut, OHNE
    // getPunkte, damit die Besucht-Markierung nicht verfaelscht wird)
    private static void einfuegen(BinTree b, ZaehlMitglied m) {
        if (b.isEmpty()) {
            b.setItem(m);
        } else {
            ZaehlMitglied w = (ZaehlMitglied) b.getItem();
            if (punkteOhneMarke(m) < punkteOhneMarke(w)) {
                einfuegen(b.getLeft(), m);
            } else {
                einfuegen(b.getRight(), m);
            }
        }
    }

    private static int punkteOhneMarke(ZaehlMitglied m) {
        boolean vorher = m.istBesucht();
        int p = m.getPunkte();
        if (!vorher) {
            m.zuruecksetzen();
        }
        return p;
    }

    // Namen aller Mitglieder, bei denen getPunkte() aufgerufen wurde (Preorder)
    public static String besucht(BinTree b) {
        if (b.isEmpty()) {
            return "";
        }
        String t = "";
        Object o = b.getItem();
        if (o instanceof ZaehlMitglied && ((ZaehlMitglied) o).istBesucht()) {
            t = ((ZaehlMitglied) o).getName() + " ";
        }
        return t + besucht(b.getLeft()) + besucht(b.getRight());
    }

    public static void alleZuruecksetzen(BinTree b) {
        if (!b.isEmpty()) {
            ((ZaehlMitglied) b.getItem()).zuruecksetzen();
            alleZuruecksetzen(b.getLeft());
            alleZuruecksetzen(b.getRight());
        }
    }

    // Name eines Mitglieds oder "null" (fuer die Meldungen der Tests)
    public static String name(Mitglied m) {
        if (m == null) {
            return "null";
        }
        return m.getName();
    }

    // Inhalt des Suchbaums in Inorder als Text (Struktur-Kontrolle)
    public static String inorder(BinTree b) {
        if (b.isEmpty()) {
            return "";
        }
        return inorder(b.getLeft()) + ((Mitglied) b.getItem()).getName() + " " + inorder(b.getRight());
    }

    // ----- Auslesen, OHNE zu veraendern -----

    // Tourenbuch von oben nach unten, z. B. "[Sandmann, Spinne]"
    public static String stapelText(Stack s) {
        Stack hilf = new Stack();
        String t = "[";
        while (!s.isEmpty()) {
            Object o = s.pop();
            if (hilf.isEmpty()) {
                t = t + ((Route) o).getName();
            } else {
                t = t + ", " + ((Route) o).getName();
            }
            hilf.push(o);
        }
        while (!hilf.isEmpty()) {
            s.push(hilf.pop());
        }
        return t + "]";
    }

    // true, wenn s von oben nach unten GENAU die Objekte erwartet[0], erwartet[1], ...
    // enthaelt (dieselben Objekte, dieselbe Reihenfolge); s bleibt unveraendert
    public static boolean stapelGleich(Stack s, Route[] erwartet) {
        Stack hilf = new Stack();
        boolean gleich = true;
        int i = 0;
        while (!s.isEmpty()) {
            Object o = s.pop();
            if (i >= erwartet.length || o != erwartet[i]) {
                gleich = false;
            }
            hilf.push(o);
            i++;
        }
        while (!hilf.isEmpty()) {
            s.push(hilf.pop());
        }
        return gleich && i == erwartet.length;
    }

    // Warteliste von vorn nach hinten als Namen
    public static String schlangeText(Queue q) {
        Queue hilf = new Queue();
        String t = "[";
        boolean erstes = true;
        while (!q.isEmpty()) {
            Object o = q.dequeue();
            if (erstes) {
                t = t + ((Mitglied) o).getName();
                erstes = false;
            } else {
                t = t + ", " + ((Mitglied) o).getName();
            }
            hilf.enqueue(o);
        }
        while (!hilf.isEmpty()) {
            q.enqueue(hilf.dequeue());
        }
        return t + "]";
    }

    // true, wenn q von vorn GENAU die Objekte erwartet[0], ... enthaelt
    public static boolean schlangeGleich(Queue q, Mitglied[] erwartet) {
        Queue hilf = new Queue();
        boolean gleich = true;
        int i = 0;
        while (!q.isEmpty()) {
            Object o = q.dequeue();
            if (i >= erwartet.length || o != erwartet[i]) {
                gleich = false;
            }
            hilf.enqueue(o);
            i++;
        }
        while (!hilf.isEmpty()) {
            q.enqueue(hilf.dequeue());
        }
        return gleich && i == erwartet.length;
    }

    // Routen einer dynamischen Reihung als Namen
    public static String reihungText(DynArray d) {
        String t = "[";
        for (int i = 0; i < d.getLength(); i++) {
            if (i > 0) {
                t = t + ", ";
            }
            t = t + ((Route) d.getItem(i)).getName();
        }
        return t + "]";
    }

    // Mitglieder einer statischen Reihung mit Punkten
    public static String reihungText(Mitglied[] t) {
        String s = "";
        for (int i = 0; i < t.length; i++) {
            if (i > 0) {
                s = s + ", ";
            }
            s = s + t[i].getName() + " " + t[i].getPunkte();
        }
        return s;
    }

    // ----- Sonstiges -----

    // Neue Zeichenkette mit demselben Inhalt (zur Laufzeit zusammengesetzt):
    // In echtem Java faellt damit == statt equals auf (P5).
    public static String kopie(String s) {
        String t = "";
        for (int i = 0; i < s.length(); i++) {
            t = t + s.charAt(i);
        }
        return t;
    }

    // Laufzeitfehler -> roter Test mit Hinweis auf die Top-10-Punktverluste
    public static void laufzeitfehler(RuntimeException e) {
        String meldung = " (Meldung: " + e.getMessage() + ")";
        try {
            throw e;
        } catch (IllegalStateException x) {
            fail("LAUFZEITFEHLER: top/pop/head/dequeue bzw. getItem/getLeft/getRight auf einer LEEREN Struktur - Leerabfrage fehlt (P1)" + meldung);
        } catch (IndexOutOfBoundsException x) {
            fail("LAUFZEITFEHLER: Index ausserhalb - gueltig sind 0 bis getLength() - 1; geloescht und danach i erhoeht? (P1/P6)" + meldung);
        } catch (IllegalArgumentException x) {
            fail("LAUFZEITFEHLER: null in Stack, Queue, DynArray oder BinTree gelegt" + meldung);
        } catch (ClassCastException x) {
            fail("LAUFZEITFEHLER: falscher Cast (P4)" + meldung);
        } catch (NullPointerException x) {
            fail("LAUFZEITFEHLER: Zugriff auf null - z. B. Methode einer nicht vorhandenen Route aufgerufen (P1)" + meldung);
        } catch (RuntimeException x) {
            fail("LAUFZEITFEHLER" + meldung);
        }
    }
}


