// ----- c) hoechsterGrad (Klasse Mitglied, Stapel)
    public int hoechsterGrad(int k) {
        Stack hilf = new Stack();
        int max = 0;
        int anzahl = 0;
        while (!tourenbuch.isEmpty() && anzahl < k) {
            Route r = (Route) tourenbuch.pop();
            if (r.getGrad() > max) {
                max = r.getGrad();
            }
            hilf.push(r);
            anzahl = anzahl + 1;
        }
        while (!hilf.isEmpty()) {
            tourenbuch.push(hilf.pop());
        }
        return max;
    }

// ----- d) abmelden (Klasse Station) - Java-Uebersetzung des Struktogramms
    public boolean abmelden(String name) {
        boolean gefunden = false;
        Queue hilf = new Queue();
        while (!warteliste.isEmpty()) {
            Mitglied m = (Mitglied) warteliste.dequeue();
            if (!gefunden && m.getName().equals(name)) {
                gefunden = true;
            } else {
                hilf.enqueue(m);
            }
        }
        while (!hilf.isEmpty()) {
            warteliste.enqueue(hilf.dequeue());
        }
        return gefunden;
    }

// ----- e) ausschrauben (Klasse Kletterhalle, dynamische Reihung)
    public int ausschrauben(String sektor) {
        int anzahl = 0;
        int i = 0;
        while (i < routen.getLength()) {
            Route r = (Route) routen.getItem(i);
            if (r.getSektor().equals(sektor)) {
                routen.delete(i);
                anzahl = anzahl + 1;
            } else {
                i = i + 1;
            }
        }
        return anzahl;
    }

// ----- f) schwersteRoute (Klasse Kletterhalle) - korrigierte Fassung
    public Route schwersteRoute(String sektor) {
        Route beste = null;
        for (int i = 0; i < routen.getLength(); i++) {
            Route r = (Route) routen.getItem(i);
            if (r.getSektor().equals(sektor)) {
                if (beste == null || r.getGrad() > beste.getGrad()) {
                    beste = r;
                }
            }
        }
        return beste;
    }

// ----- m) naechstesZiel (Klasse Kletterhalle, binaerer Suchbaum)
    public Mitglied naechstesZiel(BinTree b, int punkte) {
        if (b.isEmpty()) {
            return null;
        }
        Mitglied m = (Mitglied) b.getItem();
        if (m.getPunkte() <= punkte) {
            return naechstesZiel(b.getRight(), punkte);
        }
        Mitglied links = naechstesZiel(b.getLeft(), punkte);
        if (links == null) {
            return m;
        }
        return links;
